  ShellJobEntry entry,
  String output, {
  required num? timeoutArg,
}) {
  final exitCode = entry.exitCode ?? -1;
  if (entry.stopReason == 'timeout') {
    throw StateError(
      _appendStatus(
        output,
        'Command timed out after ${timeoutArg ?? 'unknown'} seconds',
      ),
    );
